   "contentDe": "Text: Ich habe gerne Unterricht bei ... Intention: Personen beschreiben Hörverstehen: Die kenne ich doch! Leseverstehen: Es ist auch nicht so schlimm, wenn ... Grammatik: 1. Adjektivdeklination nach unbestimmten Artikeln, Possessivpronomen und „kein“ Il. Adjektivdeklination nach Nullartikel Ill. Kausalsatz mit „weil“ IV. Konditionalsatz mit „wenn“"
